MOD = 998244353
N = int(input())
P = list(map(lambda x: int(x)-1, input().split()))
S = input()

def countValidConfigurations(N, P, S):
    from itertools import product

    def isValidConfiguration(config):
        spoonTaken = [False] * N
        for i in range(N):
            person = P[i]
            hand = config[person]
            if hand == 'L':
                if not spoonTaken[person]:
                    spoonTaken[person] = True
                else:
                    return False
            elif hand == 'R':
                if not spoonTaken[(person + 1) % N]:
                    spoonTaken[(person + 1) % N] = True
                else:
                    return False
        return all(spoonTaken)

    question_indices = [i for i, ch in enumerate(S) if ch == '?']
    validCount = 0

    for replacement in product('LR', repeat=len(question_indices)):
        config = list(S)
        for idx, char in zip(question_indices, replacement):
            config[idx] = char
        if isValidConfiguration(config):
            validCount += 1

    return validCount % MOD

print(countValidConfigurations(N, P, S))
